const route=()=>location.hash.replace(/^#\//,'').split('?')[0]||'home';
const primary=r=>r==='match'?'competition':(['home','competition','video','fantasy','more'].includes(r)?r:'more');

function toast(message){toastRoot.innerHTML=`<div class="toast">${esc(message)}</div>`;setTimeout(()=>{toastRoot.innerHTML=''},1800)}
function navigate(r){if(location.hash===`#/${r}`){window.scrollTo({top:0,behavior:'smooth'});return}location.hash=`#/${r}`;window.scrollTo(0,0)}
function setNav(){const p=primary(route());document.querySelectorAll('.nav-item').forEach(btn=>{const active=btn.dataset.route===p;btn.classList.toggle('active',active);const n=btn.dataset.nav;const key=n+(active?'Active':'');btn.querySelector('.nav-svg').innerHTML=svg(iconPaths[key]?key:n);});}

